function evidence = f90_xmed07_extract_reference_evidence(modelPath, outDir)
%f90_xmed07_extract_reference_evidence Exact-reference-only METRICS route.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
assert(strlength(taskRoot) > 0 && isfile(simuverity_official_scenarios_path()), ...
    "SimuVerity:F90:XMED07:PublicScenarioContract", ...
    "Reference extraction requires the task-local official scenario contract.");
official = jsondecode(fileread(simuverity_official_scenarios_path()));
submissionRoot = string(fileparts(modelPath));
referenceRoot = fullfile(submissionRoot, "src");
modelsRoot = fullfile(referenceRoot, "Models");
controllerRoot = fullfile(modelsRoot, "Controller");
plantRoot = fullfile(modelsRoot, "Plant");
dataRoot = fullfile(referenceRoot, "Data");
modelFile = modelPath;
softwareFile = fullfile(controllerRoot, "InfusionPumpSoftwareModel.slx");

assert(isfile(modelFile) && isfile(softwareFile), ...
    "SimuVerity:F90:XMED07:ReferenceMissing", "Pinned reference model is missing.");
assert(strcmpi(localFilePresence(modelFile), ...
    "present"), ...
    "SimuVerity:F90:XMED07:ReferenceBinding", "Pinned top-model binding mismatch.");
assert(strcmpi(localFilePresence(softwareFile), ...
    "present"), ...
    "SimuVerity:F90:XMED07:SoftwareBinding", ...
    "Pinned software-model binding mismatch.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
if strlength(generationRunId) == 0, generationRunId = "assetref_" + string(feature("getpid")); end
if ~isfolder(outDir), mkdir(outDir); end

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XMED07:Isolation", ...
    "Isolated cache and code-generation folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(modelsRoot, "-begin");
addpath(controllerRoot, "-begin");
addpath(plantRoot, "-begin");
addpath(dataRoot, "-begin");

 [~, model] = fileparts(modelPath);
software = "InfusionPumpSoftwareModel";
cleanup = onCleanup(@() localCloseModels([model, software, ...
    "MotorController", "OcclusionDetection", "Supervisory"])); %#ok<NASGU>

evidence = struct( ...
    "schema", "simuverity.f90-xmed07-evidence.v1", ...
    "task_id", "F90-XMED-07", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "compatibility_adapter", struct, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

try
    evalin("base", sprintf("run('%s')", ...
        strrep(fullfile(dataRoot, "InitializationInsulinPump.m"), ...
        "'", "''")));
    load_system(softwareFile);
    load_system(modelFile);
    load_system(fullfile(controllerRoot, "MotorController.slx"));
    evidence.load_pass = true;
    assert(str2double(get_param(model, "StopTime")) == ...
        double(official.simulation.native_stop_time_s), ...
        "SimuVerity:F90:XMED07:StopTime", "Pinned native stop time changed.");
    assert(str2double(get_param(model, "MaxStep")) == ...
        double(official.simulation.native_max_step_s), ...
        "SimuVerity:F90:XMED07:MaxStep", "Pinned native maximum step changed.");

    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout", ...
        "SaveOutput", "off", ...
        "SaveState", "off", ...
        "SimscapeLogType", "none");
    set_param(software, "SignalLogging", "on", ...
        "SignalLoggingName", "logsout");
    evidence.compatibility_adapter = ...
        localApplyR2025aLookupCompatibility;
    localEnableLogging(model, software);
    localApplyScenario(model, official.scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model, software, referenceRoot);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for index = 1:numel(official.scenarios)
        scenario = official.scenarios(index);
        rows(index).id = string(scenario.id);
        rows(index).class = string(scenario.class);
        rows(index).requested_inputs = scenario;
        try
            localApplyScenario(model, scenario);
            set_param(model, "SimulationCommand", "update");
            started = tic;
            stopTime = sprintf("%.17g", double(scenario.stop_time_s));
            evalc("simOut = sim(model, 'StopTime', stopTime, " + ...
                "'ReturnWorkspaceOutputs', 'on');");
            rows(index).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, ...
                double(scenario.stop_time_s), official.physical_contract);
            rows(index) = localFinalizeScenario(rows(index), outputs);
            clear simOut outputs
        catch ME
            rows(index).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModels([model, software, "MotorController", ...
    "OcclusionDetection", "Supervisory"]);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
fprintf("F90_XMED07_EVIDENCE load=%d update=%d compile=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    sum([evidence.scenarios.valid]), numel(evidence.scenarios), ...
    evidencePath);
end

function adapter = localApplyR2025aLookupCompatibility
% The two external PI-gain lookups are mathematically constant (5e-4 at
% every breakpoint).  R2025a enforces the source "assume in range"
% optimization as a runtime assertion when the speed error exceeds 450.
% Disabling only that optimization removes the assertion without changing
% either lookup output.  The source model is never saved.
model = "MotorController";
blocks = [
    model + "/FeedbackController/one_D_Lookup_Table"
    model + "/FeedbackController/one_D_Lookup_Table1"];
tableValues = cell(numel(blocks), 1);
for index = 1:numel(blocks)
    assert(getSimulinkBlockHandle(blocks(index), false) > 0, ...
        "SimuVerity:F90:XMED07:CompatibilityBlock", ...
        "Expected constant PI-gain lookup is missing: %s", blocks(index));
    rawTable = string(get_param(blocks(index), "Table"));
    values = evalin("base", char(rawTable));
    assert(~isempty(values) && all(isfinite(values)) && ...
        max(abs(values(:) - values(1))) <= eps(max(1, abs(values(1)))), ...
        "SimuVerity:F90:XMED07:CompatibilitySemantic", ...
        "Lookup %s is not constant; compatibility adaptation is unsafe.", ...
        blocks(index));
    tableValues{index} = double(values(:).');
    set_param(blocks(index), "RemoveProtectionInput", "off");
end
adapter = struct( ...
    "kind", "R2025a_constant_lookup_range_assertion", ...
    "applied_in_memory_only", true, ...
    "source_model_saved", false, ...
    "mathematical_output_changed", false, ...
    "blocks", blocks, ...
    "table_values", {tableValues}, ...
    "parameter", "RemoveProtectionInput", ...
    "original_value", "on", ...
    "runtime_value", "off");
end

function localEnableLogging(model, software)
topSignals = {
    model + "/Test Sequence Control", 1, "f90_motor_voltage_V";
    model + "/Plant/Rate Transition4", 1, "f90_motor_speed_RPM";
    model + "/Plant/Rate Transition2", 1, "f90_load_force_N";
    model + "/Plant/Rate Transition3", 1, "f90_piston_displacement_mm";
    model + "/Plant/Rate Transition5", 1, "f90_line_pressure_Pa";
    model + "/Plant/DeliveryLine/FlowSensor#0/Saturation", 1, ...
        "f90_upstream_flow_mm3_per_min";
    model + "/Plant/DeliveryLine/FlowSensor#1/PS-Simulink" + newline + ...
        "Converter", 1, ...
        "f90_patient_flow_mm3_per_min"};
for index = 1:size(topSignals, 1)
    localLogOutput(topSignals{index, 1}, topSignals{index, 2}, ...
        topSignals{index, 3});
end

softwareSignals = {
    software + "/Supervisory", 1, "f90_reference_speed_RPM";
    software + "/OcclusionDetection", 1, "f90_occlusion_alarm";
    software + "/Disp2Unit", 1, "f90_remaining_units"};
for index = 1:size(softwareSignals, 1)
    localLogOutput(softwareSignals{index, 1}, softwareSignals{index, 2}, ...
        softwareSignals{index, 3});
end
end

function localLogOutput(block, portIndex, name)
assert(getSimulinkBlockHandle(block, false) > 0, ...
    "SimuVerity:F90:XMED07:LogBlockMissing", "Logging block is missing: %s", block);
ports = get_param(block, "PortHandles");
assert(numel(ports.Outport) >= portIndex && ...
    ports.Outport(portIndex) > 0, ...
    "SimuVerity:F90:XMED07:LogPortMissing", "Logging port is missing: %s", block);
set_param(ports.Outport(portIndex), ...
    "DataLogging", "on", ...
    "DataLoggingNameMode", "Custom", ...
    "DataLoggingName", name);
end

function localApplyScenario(model, scenario)
nativeDeliveryType = double(scenario.delivery_mode);
if nativeDeliveryType == 3
    nativeDeliveryType = 1;
end
assignin("base", "DeliveryType", nativeDeliveryType);
assignin("base", "MagB", double(scenario.bolus_magnitude_units));
assignin("base", "StrokeTimeB", ...
    double(scenario.bolus_stroke_time_s));
assignin("base", "PauseTime", double(scenario.pause_time_s));
assignin("base", "NumCyc", double(scenario.cycle_count));
assignin("base", "F90QuickMag", ...
    double(scenario.quick_bolus_magnitude_units(:).'));
assignin("base", "F90QuickStroke", ...
    double(scenario.quick_bolus_stroke_time_s(:).'));

reservoir = evalin("base", "reserv_str");
reservoir.Occl.Time = double(scenario.occlusion_onset_s);
assignin("base", "reserv_str", reservoir);
assignin("base", "const_Occl_Pct", ...
    double(scenario.occlusion_fraction));
assignin("base", "OcclAlgorithmSelect", 1);

command = model + "/CommandGeneration";
set_param(command + "/Constant2", "Value", "DeliveryType");
set_param(command + "/Constant3", "Value", "MagB");
set_param(command + "/Constant12", "Value", "StrokeTimeB");
set_param(command + "/Constant13", "Value", "NumCyc");
set_param(command + "/Constant14", "Value", "PauseTime");
set_param(command + "/Constant15", "Value", "F90QuickMag");
set_param(command + "/Constant16", "Value", "F90QuickStroke");
set_param(command + "/Constant4", "Value", sprintf("%.17g", ...
    double(scenario.basal_rate_units_per_hour)));
set_param(command + "/Constant5", "Value", sprintf("%.17g", ...
    max(2.0, double(scenario.basal_rate_units_per_hour))));
set_param(command + "/Constant6", "Value", sprintf("%.17g", ...
    double(scenario.low_remaining_limit_units)));
isBasal = double(scenario.delivery_mode) == 3;
isBolus = any(double(scenario.delivery_mode) == [1, 2]);
set_param(command + "/Step1", "Time", "1", "Before", "0", ...
    "After", sprintf("%d", isBasal));
set_param(command + "/Step2", "Time", "1", "Before", "0", ...
    "After", sprintf("%d", isBolus));

patient = model + "/Plant/DeliveryLine/Patient/PS Constant";
set_param(patient, "constant", sprintf("%.17g", ...
    double(scenario.patient_backpressure_Pa)));
dialog = get_param(patient, "DialogParameters");
if isfield(dialog, "constant_unit")
    set_param(patient, "constant_unit", "Pa");
end
end

function audit = localStaticAudit(model, software, referenceRoot)
audit = struct( ...
    "top_command_to_software", ...
        localOutputFeeds(model + "/CommandGeneration", 1, ...
        model + "/Test Sequence Control", 1), ...
    "top_software_to_motor_plant", ...
        localOutputFeeds(model + "/Test Sequence Control", 1, ...
        model + "/Plant", 1), ...
    "top_plant_feedback_to_software", ...
        localOutputFeeds(model + "/Plant", 1, ...
        model + "/Test Sequence Control", 2), ...
    "software_reference_to_motor_controller", ...
        localOutputFeeds(software + "/Supervisory", 1, ...
        software + "/MotorController", 1), ...
    "measured_speed_to_motor_controller", ...
        localOutputFeeds(software + "/BusSelector", 2, ...
        software + "/MotorController", 2), ...
    "measured_speed_to_occlusion_detector", ...
        localOutputFeeds(software + "/BusSelector", 2, ...
        software + "/OcclusionDetection", 1), ...
    "load_force_to_occlusion_detector", ...
        localOutputFeeds(software + "/BusSelector", 3, ...
        software + "/OcclusionDetection", 2), ...
    "occlusion_to_supervisory", ...
        localOutputFeeds(software + "/OcclusionDetection", 1, ...
        software + "/Supervisory", 3), ...
    "remaining_units_to_supervisory", ...
        localOutputFeeds(software + "/Disp2Unit", 1, ...
        software + "/Supervisory", 2), ...
    "physical_motor_present", ...
        localBlockExists(model + "/Plant/DC Motor Drive"), ...
    "physical_transmission_present", ...
        localBlockExists(model + "/Plant/Drive System"), ...
    "physical_slide_present", ...
        localBlockExists(model + "/Plant/Slide"), ...
    "physical_reservoir_present", ...
        localBlockExists(model + "/Plant/Reservoir"), ...
    "physical_delivery_line_present", ...
        localBlockExists(model + "/Plant/DeliveryLine"), ...
    "physical_patient_boundary_present", ...
        localBlockExists(model + ...
        "/Plant/DeliveryLine/Patient/PS Constant"), ...
    "physical_upstream_flow_sensor_present", ...
        localBlockExists(model + ...
        "/Plant/DeliveryLine/FlowSensor#0/Hydraulic Flow Rate" + newline + ...
        "Sensor"), ...
    "physical_patient_flow_sensor_present", ...
        localBlockExists(model + ...
        "/Plant/DeliveryLine/FlowSensor#1/Hydraulic Flow Rate" + newline + ...
        "Sensor"), ...
    "native_occlusion_source_present", ...
        localBlockExists(model + ...
        "/Plant/DeliveryLine/Occlusion Generation/Step1"), ...
    "controller_component_models_present", ...
        all(isfile(fullfile(referenceRoot, "Models", "Controller", ...
        ["MotorController.slx", "OcclusionDetection.slx", ...
        "Supervisory.slx"]))));
end

function pass = localBlockExists(block)
pass = getSimulinkBlockHandle(block, false) > 0;
end

function pass = localOutputFeeds(source, sourcePort, destination, destPort)
pass = false;
if ~localBlockExists(source) || ~localBlockExists(destination)
    return
end
sourcePorts = get_param(source, "PortHandles");
destPorts = get_param(destination, "PortHandles");
if numel(sourcePorts.Outport) < sourcePort || ...
        numel(destPorts.Inport) < destPort
    return
end
line = get_param(sourcePorts.Outport(sourcePort), "Line");
if line <= 0
    return
end
destinations = get_param(line, "DstPortHandle");
pass = any(destinations == destPorts.Inport(destPort));
end

function outputs = localExtractOutputs(simOut, stopTime, contract)
logsout = localGetOutput(simOut, "logsout");
assert(isa(logsout, "Simulink.SimulationData.Dataset"), ...
    "SimuVerity:F90:XMED07:LogsMissing", ...
    "Required signal logging Dataset is missing.");

series = struct( ...
    "reference", localDatasetSeries(logsout, ...
        "f90_reference_speed_RPM"), ...
    "speed", localDatasetSeries(logsout, ...
        "f90_motor_speed_RPM"), ...
    "voltage", localDatasetSeries(logsout, ...
        "f90_motor_voltage_V"), ...
    "piston", localDatasetSeries(logsout, ...
        "f90_piston_displacement_mm"), ...
    "upstream_flow", localDatasetSeries(logsout, ...
        "f90_upstream_flow_mm3_per_min"), ...
    "patient_flow", localDatasetSeries(logsout, ...
        "f90_patient_flow_mm3_per_min"), ...
    "pressure", localDatasetSeries(logsout, ...
        "f90_line_pressure_Pa"), ...
    "force", localDatasetSeries(logsout, ...
        "f90_load_force_N"), ...
    "alarm", localDatasetSeries(logsout, ...
        "f90_occlusion_alarm"), ...
    "remaining", localDatasetSeries(logsout, ...
        "f90_remaining_units"));

time = linspace(0, stopTime, max(1501, round(stopTime / 0.02) + 1))';
reference = localInterp(series.reference, time, "previous");
speed = localInterp(series.speed, time, "linear");
voltage = localInterp(series.voltage, time, "previous");
piston = localInterp(series.piston, time, "linear");
upstreamFlow = localInterp(series.upstream_flow, time, "linear");
patientFlow = localInterp(series.patient_flow, time, "linear");
pressure = localInterp(series.pressure, time, "linear");
force = localInterp(series.force, time, "linear");
alarm = localInterp(series.alarm, time, "previous");
remaining = localInterp(series.remaining, time, "linear");

volumePerUnit = double(contract.fluid_volume_per_unit_mm3);
upstreamDelivered = cumtrapz(time, max(upstreamFlow, 0)) / ...
    60 / volumePerUnit;
patientDelivered = cumtrapz(time, max(patientFlow, 0)) / ...
    60 / volumePerUnit;
deliveryEnabled = double(abs(reference) > 1);

outputs = struct( ...
    "time_s", time, ...
    "motion_state", [reference, speed, voltage, piston], ...
    "delivery_state", [upstreamFlow, patientFlow, pressure, ...
        patientDelivered], ...
    "safety_state", [force, alarm, deliveryEnabled, remaining], ...
    "derived", struct( ...
        "upstream_cumulative_units", upstreamDelivered, ...
        "patient_cumulative_units", patientDelivered), ...
    "native_sample_counts", struct( ...
        "reference", numel(series.reference.time), ...
        "speed", numel(series.speed.time), ...
        "voltage", numel(series.voltage.time), ...
        "piston", numel(series.piston.time), ...
        "upstream_flow", numel(series.upstream_flow.time), ...
        "patient_flow", numel(series.patient_flow.time), ...
        "pressure", numel(series.pressure.time), ...
        "force", numel(series.force.time), ...
        "alarm", numel(series.alarm.time), ...
        "remaining", numel(series.remaining.time)), ...
    "logged_signal_names", string(logsout.getElementNames));
end

function row = localFinalizeScenario(row, outputs)
values = [outputs.time_s; outputs.motion_state(:); ...
    outputs.delivery_state(:); outputs.safety_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = ...
    all(isfinite(values)) && ...
    abs(outputs.time_s(1)) <= 1e-9 && ...
    outputs.time_s(end) >= double(row.requested_inputs.stop_time_s) - 1e-6 && ...
    size(outputs.motion_state, 2) == 4 && ...
    size(outputs.delivery_state, 2) == 4 && ...
    size(outputs.safety_state, 2) == 4;
row.outputs = outputs;
row.metrics = localMetrics(outputs, row.requested_inputs);
row.valid = row.required_evidence_pass;
row.error = struct;
end

function metrics = localMetrics(outputs, scenario)
t = outputs.time_s;
motion = outputs.motion_state;
delivery = outputs.delivery_state;
safety = outputs.safety_state;
ref = motion(:, 1);
speed = motion(:, 2);
voltage = motion(:, 3);
piston = motion(:, 4);
upstreamFlow = delivery(:, 1);
patientFlow = delivery(:, 2);
pressure = delivery(:, 3);
patientUnits = delivery(:, 4);
force = safety(:, 1);
alarm = safety(:, 2);
remaining = safety(:, 4);
upstreamUnits = outputs.derived.upstream_cumulative_units;

active = abs(ref) > max(1, 0.02 * max(abs(ref)));
if nnz(active) >= 2
    trackingRmse = sqrt(mean((speed(active) - ref(active)).^2));
    trackingRelativeRmse = trackingRmse / ...
        max(sqrt(mean(ref(active).^2)), eps);
    trackingP95 = localPercentile(abs(speed(active) - ref(active)), 95);
else
    trackingRmse = 0;
    trackingRelativeRmse = 0;
    trackingP95 = 0;
end

area = pi * (0.4720 * 25.4)^2 / 4;
volumePerUnit = 15;
pistonUnits = max(0, (piston(end) - piston(1)) * area / volumePerUnit);
leadMmPerMotorRev = (1 / 24) * 25.4 / 216;
targetUnits = trapz(t, max(ref, 0)) / 60 * ...
    leadMmPerMotorRev * area / volumePerUnit;
alarmOnset = localFirstTime(t, alarm > 0.5, 0);
if isfinite(alarmOnset)
    onsetIndex = find(t >= alarmOnset, 1, "first");
    postAlarmUnits = patientUnits(end) - patientUnits(onsetIndex);
    postAlarmReferenceMax = max(abs(ref(t >= alarmOnset + 2)));
else
    postAlarmUnits = NaN;
    postAlarmReferenceMax = NaN;
end

occlusionOnset = double(scenario.occlusion_onset_s);
if isfinite(alarmOnset)
    detectionDelay = alarmOnset - occlusionOnset;
else
    detectionDelay = NaN;
end

activeTransitions = sum(diff(double(active)) == 1);
metrics = struct( ...
    "reference_speed_peak_RPM", max(abs(ref)), ...
    "measured_speed_peak_RPM", max(abs(speed)), ...
    "motor_tracking_rmse_RPM", trackingRmse, ...
    "motor_tracking_relative_rmse", trackingRelativeRmse, ...
    "motor_tracking_p95_error_RPM", trackingP95, ...
    "motor_voltage_peak_V", max(abs(voltage)), ...
    "active_delivery_transition_count", activeTransitions, ...
    "target_motion_equivalent_units", targetUnits, ...
    "upstream_delivered_units", upstreamUnits(end), ...
    "patient_delivered_units", patientUnits(end), ...
    "piston_displacement_equivalent_units", pistonUnits, ...
    "patient_to_target_relative_error", ...
        abs(patientUnits(end) - targetUnits) / max(targetUnits, 1e-9), ...
    "piston_to_target_relative_error", ...
        abs(pistonUnits - targetUnits) / max(targetUnits, 1e-9), ...
    "patient_to_piston_relative_error", ...
        abs(patientUnits(end) - pistonUnits) / max(pistonUnits, 1e-9), ...
    "upstream_to_patient_relative_error", ...
        abs(upstreamUnits(end) - patientUnits(end)) / ...
        max(upstreamUnits(end), 1e-9), ...
    "patient_flow_mean_active_mm3_per_min", ...
        localMean(patientFlow(active)), ...
    "patient_flow_peak_mm3_per_min", max(patientFlow), ...
    "line_pressure_peak_Pa", max(pressure), ...
    "line_pressure_final_Pa", pressure(end), ...
    "load_force_peak_N", max(force), ...
    "occlusion_alarm_onset_s", alarmOnset, ...
    "occlusion_detection_delay_s", detectionDelay, ...
    "post_alarm_delivered_units", postAlarmUnits, ...
    "post_alarm_reference_speed_max_RPM", postAlarmReferenceMax, ...
    "alarm_fraction", mean(alarm > 0.5), ...
    "remaining_units_initial", remaining(1), ...
    "remaining_units_final", remaining(end), ...
    "remaining_units_change", remaining(end) - remaining(1), ...
    "commanded_mode", double(scenario.delivery_mode), ...
    "requested_basal_rate_units_per_hour", ...
        double(scenario.basal_rate_units_per_hour), ...
    "requested_occlusion_fraction", ...
        double(scenario.occlusion_fraction));
end

function value = localMean(values)
if isempty(values), value = NaN; else, value = mean(values); end
end

function value = localFirstTime(time, mask, threshold)
index = find(mask & time >= threshold, 1, "first");
if isempty(index), value = NaN; else, value = time(index); end
end

function value = localPercentile(values, percentile)
values = sort(double(values(:)));
if isempty(values)
    value = NaN;
    return
end
position = 1 + (numel(values) - 1) * percentile / 100;
lower = floor(position);
upper = ceil(position);
if lower == upper
    value = values(lower);
else
    fraction = position - lower;
    value = values(lower) * (1 - fraction) + values(upper) * fraction;
end
end

function series = localDatasetSeries(dataset, name)
element = localFindDatasetElement(dataset, name);
assert(~isempty(element), "SimuVerity:F90:XMED07:SignalMissing", ...
    "Required logged signal %s is missing. Available: %s", ...
    name, strjoin(string(dataset.getElementNames), ", "));
value = element.Values;
assert(isa(value, "timeseries"), "SimuVerity:F90:XMED07:SignalType", ...
    "Required logged signal %s is not a Timeseries.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(time) && size(data, 2) == numel(time)
    data = data.';
end
assert(size(data, 1) == numel(time) && size(data, 2) == 1, ...
    "SimuVerity:F90:XMED07:SignalShape", ...
    "Required logged signal %s has an invalid shape.", name);
[time, uniqueIndex] = unique(time, "stable");
data = data(uniqueIndex, :);
assert(numel(time) >= 2 && all(isfinite(time)) && ...
    all(isfinite(data), "all"), "SimuVerity:F90:XMED07:SignalInvalid", ...
    "Required logged signal %s is incomplete or nonfinite.", name);
series = struct("time", time, "values", data);
end

function element = localFindDatasetElement(dataset, name)
element = dataset.getElement(char(name));
if ~isempty(element)
    return
end
element = [];
for index = 1:numElements(dataset)
    candidate = dataset.getElement(index);
    if strcmp(string(candidate.Name), string(name))
        element = candidate;
        return
    end
    if isa(candidate.Values, "Simulink.SimulationData.Dataset")
        element = localFindDatasetElement(candidate.Values, name);
        if ~isempty(element), return; end
    end
end
end

function values = localInterp(series, time, method)
values = interp1(series.time, series.values, time, method, "extrap");
values = double(values(:));
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "class", "", ...
    "requested_inputs", struct, ...
    "simulation_wall_clock_s", NaN, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "outputs", struct, ...
    "metrics", struct, ...
    "error", struct);
end

function value = localGetOutput(simOut, name)
try
    value = simOut.get(name);
catch
    value = [];
end
if isempty(value) && evalin("base", sprintf("exist('%s','var')", name))
    value = evalin("base", name);
end
end

function localCloseModels(models)
for index = 1:numel(models)
    try
        if bdIsLoaded(models(index))
            close_system(models(index), 0);
        end
    catch
    end
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function root = localRepoRoot
root = fileparts(fileparts(fileparts(fileparts(fileparts( ...
    mfilename("fullpath"))))));
end

function value = localNow
value = string(datetime("now", "TimeZone", "UTC", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
end

function output = localError(ME)
output = struct( ...
    "identifier", string(ME.identifier), ...
    "message", string(ME.message), ...
    "report", string(getReport(ME, "extended", ...
    "hyperlinks", "off")));
end

function localWriteJson(path, value)
text = jsonencode(value, "PrettyPrint", true);
fid = fopen(path, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XMED07:Write", "Cannot write %s.", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", text);
end

